import {api} from './auth.js';
import {amount,today,uid,eventTotals} from './model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=n=>(n/100).toLocaleString('ru-RU',{maximumFractionDigits:2})+' ₽';
const categories=['Зарплата','Аванс','Премия','Отпускные','Больничный / командировка','Кэшбэк','Проценты','Дивиденды','Проценты / дивиденды','Кэшбэк / проценты','Прочее'];
const salary=c=>categories.slice(0,5).includes(c);
export function demoFinance(){
 const incomes=[];for(const y of [2025,2026])for(let m=1;m<=(y===2026?9:12);m++){const month=`${y}-${String(m).padStart(2,'0')}`;for(const [category,value,day] of [['Зарплата',51000+(m%3)*1800,10],['Аванс',26000,25],['Кэшбэк',600+m*120,12],['Проценты',1800+m*80,20]])incomes.push({id:uid(),category,amount:Math.round(value*(y===2026?1.12:1)*100),date:`${month}-${day}`,month,bank:'Т-Банк',note:'Пример'});if(m===5)incomes.push({id:uid(),category:'Премия',amount:1800000,date:`${month}-15`,month,bank:'Сбер',note:'Пример'});}
 return {incomes,sales:[{id:uid(),name:'Визитки · заказ 120 шт.',date:'2026-09-18',revenue:72000,cost:30000,received:72000,quantity:120,productId:''},{id:uid(),name:'USB-светильник',date:'2026-09-22',revenue:180000,cost:78000,received:120000,quantity:3,productId:''},{id:uid(),name:'Пузырьчатая плёнка',date:'2026-08-12',revenue:140000,cost:64000,received:140000,quantity:2,productId:''}],stock:[{id:uid(),name:'USB-светильник',quantity:8,cost:26000,price:60000,source:'OZON'},{id:uid(),name:'Пузырьчатая плёнка',quantity:5,cost:32000,price:70000,source:'WB'},{id:uid(),name:'Обложка для паспорта',quantity:12,cost:8500,price:25000,source:'Закупка'}],accounts:[{id:uid(),name:'Т-Банк · карта',balance:4250000},{id:uid(),name:'Сбер · накопительный',balance:18000000},{id:uid(),name:'OZON · карта',balance:730000}],reserved:2500000,credit:1200000,mortgages:[{id:uid(),name:'Ипотека · пример',initial:272000000,balance:23337543,payments:[]}],family:[{id:uid(),name:'Расчёты с бабулей · пример',balance:16000000,payments:[]}]};
}
export function cardTotals(order){const cost=order.costOverride??Math.round(order.quantity*order.unitCost),revenue=order.revenueOverride??Math.round(order.actualQuantity*order.unitPrice);return {cost,revenue,plannedProfit:revenue-cost,profit:order.received-cost,debt:Math.max(0,revenue-order.received),overpayment:Math.max(0,order.received-revenue)};}
export function financeTotals(data,year,month='all',kind='all'){
 const matches=period=>period.startsWith(year+'-')&&(month==='all'||period===`${year}-${month}`);
 const incomes=data.incomes.filter(x=>matches(x.month)&&(kind==='all'||x.category===kind));const sales=kind==='all'||kind==='Продажи'?[...data.sales,...(data.cards||[]).map(x=>({...x,...cardTotals(x),name:'Визитки · '+x.name,card:true}))].filter(x=>matches(x.incomeMonth||x.date.slice(0,7))):[];
 const employment=incomes.filter(x=>salary(x.category)).reduce((n,x)=>n+x.amount,0),profit=sales.reduce((n,x)=>n+x.received-x.cost,0),other=incomes.filter(x=>!salary(x.category)).reduce((n,x)=>n+x.amount,0);
 return {total:employment+other+profit,salary:employment,other:other+profit,profit,incomes,sales};
}
export async function startFinance(root,user){
 const link=document.createElement('link');link.rel='stylesheet';link.href='/finance.css';document.head.append(link);
 const key='money-finance-account-v1-'+user.id;let state=await api('/api/finance'),data=state.data,revision=state.revision,lastSynced=structuredClone(data);let workEvents=[],workAvailable=false;try{const work=await api('/api/state');workEvents=work.data.events;workAvailable=true;}catch{}
 if(!data.cards){data.cards=data.sales.filter(x=>x.name.startsWith('Визитки')).map(x=>({id:x.id,name:'Тестовый заказчик',date:x.date,quantity:x.quantity,actualQuantity:x.quantity,unitCost:Math.round(x.cost/x.quantity),unitPrice:Math.round(x.revenue/x.quantity),received:x.received,note:''}));data.sales=data.sales.filter(x=>!x.name.startsWith('Визитки'));}
 for(const x of data.cards)if(!x.payments)x.payments=x.received?[{id:uid(),amount:x.received,date:'',note:'Ранее учтённая сумма · дата оплаты не указана'}]:[];
 let cardStatus='history',cardYear='all',cardMonth='all',cardSearch='';
 let tab='overview',year=2026,month='all',kind='all';const modal=document.getElementById('modal');
 const save=async()=>{try{const result=await api('/api/finance',{method:'PUT',body:JSON.stringify({revision,data})});revision=result.revision;data=result.data;lastSynced=structuredClone(data);localStorage.setItem(key,JSON.stringify(data));render();}catch(e){data=structuredClone(lastSynced);throw e;}};
 function download(value,name){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 async function importFile(file){try{const input=JSON.parse(await file.text());if(!['money-finance-import-v1','money-finance-backup-v1'].includes(input.format))throw Error('Выберите файл импорта или резервную копию.');if(input.format==='money-finance-backup-v1')input.data.importMeta={...(input.data.importMeta||{}),id:'restore-'+Date.now(),filename:'Резервная копия',monthly:input.data.importMeta?.monthly||[]};form('Загрузить финансовые данные',`<p>Будут загружены ${input.data.incomes.length} поступлений, ${input.data.cards.length} заказов визиток и ${input.data.sales.length} продаж. Текущий раздел «Доход» будет заменён. Перед заменой сохраняется резервная копия; «Работа» не изменяется.</p><p>Расхождения с Excel доступны в сверке. Их исправление не выполняется автоматически.</p>`,'Перенести',async()=>{download({format:'money-finance-backup-v1',data},'finance-before-import.json');const result=await api('/api/finance/import',{method:'POST',body:JSON.stringify({revision,data:input.data})});data=result.data;revision=result.revision;lastSynced=structuredClone(data);tab='more';});}catch(e){alert(e.message);}}
 const btn=(action,label,extra='')=>`<button data-fin="${action}" ${extra}>${label}</button>`;
 const options=(list,selected)=>list.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join('');
 const field=(label,name,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
 function form(title,body,submit,apply){modal.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button id="fin-close" aria-label="Закрыть">✕</button></div><form class="modal-body">${body}<p class="error" role="alert"></p><div class="modal-buttons"><button type="button" id="fin-cancel">Отмена</button><button type="submit" class="primary">${submit}</button></div></form>`;modal.showModal();modal.querySelector('#fin-close').onclick=modal.querySelector('#fin-cancel').onclick=()=>modal.close();modal.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const submit=ev.target.querySelector('[type=submit]');submit.disabled=true;try{await apply(new FormData(ev.target));await save();modal.close();}catch(e){modal.querySelector('.error').textContent=e.message;}finally{submit.disabled=false;}};}
 function overview(){const t=financeTotals(data,year,month),months=[...new Set([...t.incomes.map(x=>x.month),...t.sales.map(x=>x.incomeMonth||x.date.slice(0,7))])],n=months.length||1;
 const prev=financeTotals(data,year-1,month);const cutoff=month==='all'?Math.max(0,...months.map(x=>Number(x.slice(5)))):Number(month);const comparable=month==='all'?Array.from({length:cutoff},(_,i)=>financeTotals(data,year-1,String(i+1).padStart(2,'0')).total).reduce((a,b)=>a+b,0):prev.total;
 const growth=comparable?((t.total-comparable)/comparable*100).toFixed(1):null;const vals=Array.from({length:12},(_,i)=>financeTotals(data,year,String(i+1).padStart(2,'0'))),max=Math.max(1,...vals.map(x=>x.total));
 const groups=new Map();for(const x of t.incomes)groups.set(x.category,(groups.get(x.category)||0)+x.amount);if(t.sales.length)groups.set('Прибыль от продаж',t.profit);
 return `<div class="fin-kpis">${[['Всего доходов',t.total],['Зарплата и выплаты',t.salary],['Без зарплаты',t.other],['Прибыль от продаж',t.profit]].map(([l,v])=>`<article class="panel"><span class="muted">${l}</span><strong>${rub(v)}</strong></article>`).join('')}</div><div class="fin-duo"><section class="panel"><div class="row between"><h3>Доходы по месяцам</h3><span class="muted">${year}</span></div><div class="fin-chart" role="img" aria-label="Доход по месяцам: зарплата зелёным, остальные доходы синим">${vals.map((v,i)=>`<button class="fin-bar" data-fin="month" data-month="${String(i+1).padStart(2,'0')}" aria-label="${i+1} месяц: ${rub(v.total)}"><div class="fin-bar-space"><span class="fin-bar-other" style="height:${Math.max(0,(v.total-v.salary)/max*100)}%"></span><span style="height:${v.salary/max*100}%"></span></div><small>${['Я','Ф','М','А','М','И','И','А','С','О','Н','Д'][i]}</small></button>`).join('')}</div><p class="muted">● Зарплата и выплаты · <span class="fin-blue">● Остальные доходы</span></p><p class="footnote">Нажмите на месяц, чтобы открыть подробности. Баллы Спасибо учитываются отдельно.</p></section><section class="panel"><h3>Источники дохода</h3>${data.bonuses?.length?`<p class="footnote">Спасибо / СберМаркет: ${(data.bonuses.filter(x=>x.month.startsWith(year+'-')&&(month==='all'||x.month===year+'-'+month)).reduce((n,x)=>n+x.amount,0)/100).toLocaleString('ru-RU')} баллов · отдельно от рублей</p>`:''}${[...groups].sort((a,b)=>b[1]-a[1]).map(([c,a])=>`<button class="fin-source" data-fin="category" data-kind="${c==='Прибыль от продаж'?'Продажи':esc(c)}"><span>${esc(c)}</span><strong>${rub(a)}</strong></button>`).join('')}</section></div><div class="fin-duo"><section class="panel"><h3>Сравнение и среднее</h3><p class="fin-metric">${growth===null?'Нет данных для сравнения':`${Number(growth)>0?'+':''}${growth}%`}</p><p class="muted">К тому же периоду ${year-1} года${month==='all'?' · январь–'+cutoff:''}</p><p class="footnote">Среднее за ${n} мес. с записями: <b>${rub(Math.round(t.total/n))}</b></p></section><section class="panel"><h3>Деньги и обязательства</h3>${accountSummary()}${btn('accounts','Открыть счета →','class="textlink"')}</section></div>`;
 }
 function accountSummary(){const balance=data.accounts.filter(x=>x.owned!==false).reduce((n,x)=>n+x.balance,0),workDue=workEvents.reduce((n,x)=>n+Math.max(0,eventTotals(x).remaining),0);return `<div class="fin-line"><span>На счетах</span><b>${rub(balance)}</b></div><div class="fin-line"><span>Долг по кредиткам</span><b>${rub(data.credit)}</b></div><div class="fin-line"><span>Зарезервировано</span><b>${rub(data.reserved)}</b></div><div class="fin-line"><span>Осталось передать · Работа</span><b>${workAvailable?rub(workDue):'Нет связи'}</b></div><div class="fin-line"><span>Свободно</span><b>${workAvailable?rub(balance-data.credit-data.reserved-workDue):'Уточняется'}</b></div>`;}
 function incomesView(){const t=financeTotals(data,year,month,kind),rows=[...t.incomes.map(x=>({...x,label:x.category})),...t.sales.map(x=>({...x,label:'Продажи · '+x.name,amount:x.received-x.cost,month:x.incomeMonth||x.date.slice(0,7),sale:true}))].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="row between"><h3>Поступления · ${rub(t.total)}</h3>${btn('income','＋ Добавить','class="primary"')}</div><p class="footnote">Прибыль от продаж рассчитывается автоматически. Получено минус себестоимость всего заказа. Для импорта сохранены расчёты Excel.</p><label class="fin-filter">Источник<select id="fin-kind">${options(['all',...categories,'Продажи'],kind).replace('>all<','>Все источники<')}</select></label><section class="panel">${rows.map(x=>`<div class="fin-entry"><div class="grow"><strong>${esc(x.label)}</strong><p class="muted">${esc(x.date)} · за ${esc(x.month)}${x.bank?' · '+esc(x.bank):''}</p>${x.note?`<p class="muted">${esc(x.note)}</p>`:''}</div><b>${rub(x.amount)}</b>${!x.sale?btn(x.salaryAdjustment?'salary-month':'edit-income','✎',`data-id="${x.id}" data-month="${x.month}" aria-label="Изменить поступление"`):''}</div>`).join('')||'<p class="muted">За этот период записей нет. Добавьте поступление.</p>'}</section>`;}
 function salesView(){return `<div class="row between"><h3>Продажи</h3>${btn('sale','＋ Продажа','class="primary"')}</div><p class="footnote">Частичная оплата видна отдельно. Для истории сохранён месяц учёта из Excel; он может отличаться от даты продажи.</p><div class="fin-cards">${data.sales.map(x=>`<article class="panel"><span class="badge ${x.received>=x.revenue?'complete':''}">${x.profitOnly?'Прибыль из Excel':x.received>=x.revenue?'Оплачено':'Есть долг'}</span><h3>${esc(x.name)}</h3><p class="muted">${x.date} · ${x.quantity} шт.</p>${x.profitOnly?'<p class="footnote">В Excel указана только прибыль. Цена продажи, сумма оплаты и себестоимость не указаны.</p>':`<div class="fin-line"><span>Продажа</span><b>${rub(x.revenue)}</b></div><div class="fin-line"><span>Получено</span><b>${rub(x.received)}</b></div><div class="fin-line"><span>Себестоимость и расходы</span><b>${rub(x.cost)}</b></div>`}<div class="fin-line"><span>Фактическая прибыль</span><b>${rub(x.received-x.cost)}</b></div>${x.received<x.revenue?btn('sale-pay',`Получить остаток ${rub(x.revenue-x.received)}`,`data-id="${x.id}" class="secondary full"`):''}</article>`).join('')}</div>`;}
 const salaryFields=[['ЗП','Зарплата'],['Аванс','Аванс'],['Премия','Премия'],['Отпускные','Отпускные'],['Больничный / командировка','Больничный / командировка']];
 const monthName=m=>new Date(Number(m.slice(0,4)),Number(m.slice(5))-1,1).toLocaleDateString('ru-RU',{month:'long'});
 function salaryValues(period){return salaryFields.map(([,category])=>data.incomes.filter(x=>x.month===period&&x.category===category).reduce((n,x)=>n+x.amount,0));}
 function salaryView(){const periods=Array.from({length:12},(_,i)=>`${year}-${String(i+1).padStart(2,'0')}`).filter(p=>month==='all'||p.slice(5)===month),totals=periods.map(p=>salaryValues(p).reduce((a,b)=>a+b,0)),total=totals.reduce((a,b)=>a+b,0),filled=periods.filter(p=>data.incomes.some(x=>x.month===p&&salary(x.category))).length;return `<div class="fin-kpis"><article class="panel"><span class="muted">Итого за выбранный период</span><strong>${rub(total)}</strong></article><article class="panel"><span class="muted">Средняя за ${filled} заполненных мес.</span><strong>${filled?rub(Math.round(total/filled)):'—'}</strong></article><article class="panel"><span class="muted">Средняя за 12 месяцев</span><strong>${month==='all'?rub(Math.round(total/12)):'—'}</strong></article><article class="panel"><span class="muted">Год</span><strong>${year}</strong></article></div><div class="row between"><h3>Зарплата по месяцам</h3>${btn('salary-month','＋ Заполнить месяц',`data-month="${year}-${month==='all'?'10':month}" class="primary"`)}</div><p class="footnote">Нажмите на месяц для ввода всех выплат. ТПР — изменение к тому же месяцу прошлого года. Зарплата и аванс учитываются один раз.</p><div class="salary-months">${periods.map((p,i)=>{const v=salaryValues(p),t=totals[i],prior=salaryValues(`${year-1}-${p.slice(5)}`).reduce((a,b)=>a+b,0),growth=prior?((t-prior)/prior*100).toFixed(1):null,has=data.incomes.some(x=>x.month===p&&salary(x.category));return `<article class="panel"><button class="salary-month-title" data-fin="salary-month" data-month="${p}"><h3>${monthName(p)}</h3><b>${has?rub(t):'Заполнить ＋'}</b></button>${salaryFields.map(([label],j)=>`<div class="fin-line"><span>${label}</span><b>${v[j]?rub(v[j]):'—'}</b></div>`).join('')}<p class="footnote">ТПР: ${!has?'месяц не заполнен':growth===null?'нет базы для сравнения':`${Number(growth)>0?'+':''}${growth}%`}</p></article>`;}).join('')}</div>`;}
 function salaryForm(period){const existing=salaryValues(period);form('Зарплата за месяц',field('Месяц','period',period,'month','required')+salaryFields.map(([label],i)=>field(label+', ₽','pay-'+i,existing[i]?existing[i]/100:'','number','min="0" step="0.01" inputmode="decimal"')).join('')+'<section class="panel fin-card-calc salary-preview" aria-live="polite"></section><p class="footnote">Укажите общую сумму каждого вида выплаты за месяц. Пустое поле означает 0. Если месяц уже заполнен, значения изменят его итог, а не добавятся повторно.</p>','Сохранить зарплату',f=>{const selected=f.get('period'),values=salaryFields.map((_,i)=>{const raw=f.get('pay-'+i);return !raw||Number(raw)===0?0:amount(raw);}),current=salaryValues(selected);for(let i=0;i<values.length;i++){const difference=values[i]-current[i];if(!difference)continue;const category=salaryFields[i][1],adjustment=data.incomes.find(x=>x.salaryAdjustment&&x.category===category&&x.month===selected);if(adjustment){adjustment.amount+=difference;adjustment.date=today();}else data.incomes.push({id:uid(),category,amount:difference,date:today(),month:selected,bank:'Сводный ввод зарплаты',note:'Из формы зарплаты за месяц',salaryAdjustment:true});}year=Number(selected.slice(0,4));month='all';tab='salary';});const update=()=>{const f=new FormData(modal.querySelector('form')),selected=f.get('period');let total=0;try{for(let i=0;i<5;i++){const raw=f.get('pay-'+i);total+=!raw||Number(raw)===0?0:amount(raw);}const previous=salaryValues(`${Number(selected.slice(0,4))-1}-${selected.slice(5)}`).reduce((a,b)=>a+b,0);modal.querySelector('.salary-preview').innerHTML=`<div class="fin-line"><span>Итого за месяц</span><b>${rub(total)}</b></div><div class="fin-line"><span>ТПР к прошлому году</span><b>${previous?((total-previous)/previous*100).toFixed(1)+'%':'—'}</b></div>`;}catch{modal.querySelector('.salary-preview').textContent='Проверьте введённые суммы.';}};modal.querySelector('[name="period"]').onchange=e=>{const v=salaryValues(e.target.value);for(let i=0;i<5;i++)modal.querySelector(`[name="pay-${i}"]`).value=v[i]?v[i]/100:'';update();};modal.querySelector('form').addEventListener('input',update);update();}
 function cardsView(){const orders=data.cards.filter(x=>(cardStatus==='history'?cardTotals(x).debt===0:cardTotals(x).debt>0)&&(cardYear==='all'||x.date.startsWith(cardYear+'-'))&&(cardMonth==='all'||x.date.slice(5,7)===cardMonth)&&x.name.toLocaleLowerCase('ru').includes(cardSearch.toLocaleLowerCase('ru'))).sort((a,b)=>b.date.localeCompare(a.date)||a.name.localeCompare(b.name,'ru')),sum=orders.reduce((a,x)=>{const t=cardTotals(x);a.received+=x.received;a.cost+=t.cost;a.profit+=t.profit;a.debt+=t.debt;return a;},{received:0,cost:0,profit:0,debt:0});return `<div class="row between"><h3>Визитки · ${orders.length} заказов</h3>${btn('card','＋ Заказ','class="primary"')}</div><div class="segmented fin-card-tabs">${btn('card-status','Не оплачены · '+data.cards.filter(x=>cardTotals(x).debt>0).length,`data-status="unpaid" class="${cardStatus==='unpaid'?'selected':''}"`)}${btn('card-status','История · '+data.cards.filter(x=>cardTotals(x).debt===0).length,`data-status="history" class="${cardStatus==='history'?'selected':''}"`)}</div><div class="fin-card-filters"><label>Поиск по ФИО<input id="card-search" value="${esc(cardSearch)}" placeholder="Фамилия или заказчик" type="search"></label><label>Год заказа<select id="card-year"><option value="all">Все годы</option>${[...new Set(data.cards.map(x=>x.date.slice(0,4)))].sort().reverse().map(y=>`<option value="${y}" ${y===cardYear?'selected':''}>${y}</option>`).join('')}</select></label><label>Месяц заказа<select id="card-month"><option value="all">Все месяцы</option>${Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${cardMonth===String(i+1).padStart(2,'0')?'selected':''}>${new Date(2026,i,1).toLocaleDateString('ru-RU',{month:'long'})}</option>`).join('')}</select></label></div><p class="footnote">${cardStatus==='history'?'Оплаченные заказы.':'Заказы с остатком оплаты.'} Итоги ниже — по выбранным фильтрам. Период определяется датой заказа.</p><div class="fin-kpis">${[['Получено',sum.received],['Себестоимость',sum.cost],['Доход (факт)',sum.profit],['Осталось получить',sum.debt]].map(([l,v])=>`<article class="panel"><span class="muted">${l}</span><strong>${rub(v)}</strong></article>`).join('')}</div><div class="fin-cards">${orders.map(x=>{const t=cardTotals(x);return `<article class="panel"><span class="badge ${!t.debt?'complete':''}">${t.debt?'Есть долг':t.overpayment?'Переплата':'Оплачено'}</span><h3>${esc(x.name)}</h3><p class="muted">${esc(x.date)}</p>${[['Кол-во',x.quantity+' шт.'],['Кол-во (факт)',x.actualQuantity+' шт.'],['Цена закупки за 1 шт.',rub(x.unitCost)],['Цена за 1 шт. с наценкой',rub(x.unitPrice)],['Себестоимость',rub(t.cost)],['Должны (факт)',rub(t.revenue)],['Доход',rub(t.plannedProfit)],['Получено',rub(x.received)],['Доход (факт)',rub(t.profit)],['Осталось получить',rub(t.debt)],...(t.overpayment?[['Переплата',rub(t.overpayment)]]:[])].map(([l,v])=>`<div class="fin-line"><span>${l}</span><b>${v}</b></div>`).join('')}${x.note?`<p class="footnote">${esc(x.note)}</p>`:''}<details class="fin-payments"><summary>История оплат · ${(x.payments||[]).length}</summary>${(x.payments||[]).slice().reverse().map(p=>`<div class="fin-line"><span>${p.date?esc(p.date):'Дата не указана'}${p.note?`<small class="muted" style="display:block">${esc(p.note)}</small>`:''}</span><b>${rub(p.amount)}</b></div>`).join('')||'<p class="footnote">Оплат пока нет.</p>'}</details><div class="actions">${btn('edit-card','Изменить',`data-id="${x.id}" class="secondary"`)}${btn('card-payment','Учесть оплату',`data-id="${x.id}" class="primary"`)}</div></article>`;}).join('')||'<section class="panel"><p class="muted">По этим фильтрам заказов нет.</p></section>'}</div>`;}
 function cardForm(id){const x=data.cards.find(x=>x.id===id);form(x?'Изменить заказ визиток':'Заказ визиток',field('ФИО / заказчик','name',x?.name||'','text','required maxlength="200"')+field('Дата заказа','date',x?.date||today(),'date','required')+`<div class="fields">${field('Кол-во','quantity',x?.quantity||96,'number','required min="1" step="1" max="1000000"')}${field('Кол-во (факт)','actualQuantity',x?.actualQuantity??96,'number','required min="0" step="1" max="1000000"')}${field('Цена закупки за 1 шт., ₽','unitCost',x?x.unitCost/100:2.5,'number','required min="0" step="0.01"')}${field('Цена за 1 шт. с наценкой, ₽','unitPrice',x?x.unitPrice/100:3.6,'number','required min="0" step="0.01"')}</div>`+field('Получено, ₽','received',x?x.received/100:0,'number','required min="0" step="0.01"')+`<section class="fin-card-calc panel" aria-live="polite"></section>`+field('Комментарий','note',x?.note||'','text','maxlength="500"')+'<p class="footnote">Себестоимость = кол-во × закупочная цена. Должны (факт) = фактическое кол-во × цена с наценкой. Доход = должны − себестоимость. Доход (факт) = получено − себестоимость.</p>','Сохранить заказ',f=>{const record=cardInput(f);if(x){if(record.quantity===x.quantity&&record.unitCost===x.unitCost&&x.costOverride!==undefined)record.costOverride=x.costOverride;if(record.actualQuantity===x.actualQuantity&&record.unitPrice===x.unitPrice&&x.revenueOverride!==undefined)record.revenueOverride=x.revenueOverride;}record.id=x?.id||uid();record.payments=x?.payments||[];const difference=record.received-(x?.received||0);if(difference)record.payments.push({id:uid(),amount:difference,date:today(),note:x?'Корректировка суммы «Получено»':'Сумма при создании заказа'});if(x){delete x.costOverride;delete x.revenueOverride;Object.assign(x,record);}else data.cards.push(record);cardStatus=cardTotals(record).debt?'unpaid':'history';cardYear='all';cardMonth='all';cardSearch='';tab='cards';});const update=()=>{const out=modal.querySelector('.fin-card-calc');try{const f=new FormData(modal.querySelector('form')),draft=cardInput(f,true);if(x){if(draft.quantity===x.quantity&&draft.unitCost===x.unitCost&&x.costOverride!==undefined)draft.costOverride=x.costOverride;if(draft.actualQuantity===x.actualQuantity&&draft.unitPrice===x.unitPrice&&x.revenueOverride!==undefined)draft.revenueOverride=x.revenueOverride;}const t=cardTotals(draft);out.innerHTML=[['Себестоимость',t.cost],['Должны (факт)',t.revenue],['Доход',t.plannedProfit],['Доход (факт)',t.profit],['Осталось получить',t.debt],...(t.overpayment?[['Переплата',t.overpayment]]:[])].map(([l,n])=>`<div class="fin-line"><span>${l}</span><b>${rub(n)}</b></div>`).join('');}catch{out.textContent='Заполните количество и цены для расчёта.';}};modal.querySelector('form').addEventListener('input',update);update();}
 function cardInput(f,preview=false){const quantity=Number(f.get('quantity')),actualQuantity=Number(f.get('actualQuantity'));if(!Number.isInteger(quantity)||quantity<1||quantity>1000000||!Number.isInteger(actualQuantity)||actualQuantity<0||actualQuantity>1000000)throw Error('Проверьте количество визиток.');const cents=k=>Number(f.get(k))===0?0:amount(f.get(k));return {name:f.get('name').trim(),date:f.get('date'),quantity,actualQuantity,unitCost:cents('unitCost'),unitPrice:cents('unitPrice'),received:cents('received'),note:f.get('note').trim()};}
 function stockView(){return `<div class="row between"><h3>Склад · ${data.stock.reduce((n,x)=>n+x.quantity,0)} шт.</h3>${btn('stock','＋ Товар','class="primary"')}</div><p class="footnote">Стоимость остатков: ${rub(data.stock.reduce((n,x)=>n+x.quantity*x.cost,0))}. Потенциальная прибыль: ${rub(data.stock.reduce((n,x)=>n+x.quantity*(x.price-x.cost),0))} — в доходы не включается.</p><div class="fin-cards">${data.stock.map(x=>`<article class="panel"><h3>${esc(x.name)}</h3><p class="muted">${esc(x.source)} · остаток ${x.quantity} шт.</p><div class="fin-line"><span>Закупка за штуку</span><b>${rub(x.cost)}</b></div><div class="fin-line"><span>Цена продажи</span><b>${rub(x.price)}</b></div>${btn('sell-stock','Продать',`data-id="${x.id}" class="secondary full" ${x.quantity?'':'disabled'}`)}</article>`).join('')}</div>`;}
 function auditView(){if(!data.importMeta)return '';const rows=data.importMeta.monthly||[];return `<section class="panel"><h3>Сверка с Excel</h3><p class="footnote">Результат проверки на момент импорта; последующие изменения записей отражаются в текущем обзоре.</p><p class="footnote">Разница считается по исходным записям. Баллы отдельно от рублей; ошибки и пропуски формул не исправляются автоматически.</p>${[2025,2026].map(y=>{const a=rows.filter(x=>x.month.startsWith(y+'-'));return `<h3>${y}</h3><div class="fin-line"><span>Зарплата</span><b>${rub(a.reduce((n,x)=>n+x.importSalary,0))}</b></div><div class="fin-line"><span>Прибыль от визиток и продаж</span><b>${rub(a.reduce((n,x)=>n+x.importExtra,0))}</b></div>`;}).join('')}<details><summary>Помесячные расхождения</summary>${rows.filter(x=>x.difference||x.extraDifference).map(x=>`<div class="fin-line"><span>${x.month} · разница с Excel</span><b>${rub(x.difference)}</b></div>`).join('')}</details><details><summary>Замечания к источнику</summary>${(data.importMeta.warnings||[]).map(x=>`<p class="footnote">${esc(x)}</p>`).join('')}${(data.importMeta.unresolved||[]).map(x=>`<p class="footnote">${esc(x.section)}: ${esc(x.reason)}</p>`).join('')}<p class="footnote">Доп. заработок: в Excel пропущены записи на 500 ₽ за август 2025 и 700 ₽ за январь 2026. Сохранены все исходные записи; поэтому суммы отличаются.</p></details></section>`;}
 function moreView(){return `${auditView()}<div class="fin-duo"><section class="panel"><h3>Счета</h3>${accountSummary()}${data.accounts.map(x=>`<button class="fin-source" data-fin="account" data-id="${x.id}"><span>${esc(x.name)}${x.owned===false?' · чужие средства':''}</span><b>${rub(x.balance)} ✎</b></button>`).join('')}${btn('limits','Изменить долг и резерв','class="textlink"')}</section><section class="panel"><h3>Ипотеки</h3>${data.mortgages.map(x=>`<h3>${esc(x.name)}</h3><p class="fin-metric">${rub(x.balance)}</p><p class="muted">Погашено ${Math.round((1-x.balance/x.initial)*100)}%</p>${btn('mortgage','Добавить платёж',`data-id="${x.id}" class="secondary"`)}<p class="footnote">Записано платежей: ${x.payments.length}</p>`).join('')}</section><section class="panel"><h3>Семейные расчёты</h3>${data.family.map(x=>`<p>${esc(x.name)}</p><p class="fin-metric">${rub(x.balance)}</p>${btn('family','Учесть расход',`data-id="${x.id}" class="secondary"`)}<p class="footnote">Записано операций: ${x.payments.length}</p>`).join('')}</section><section class="panel"><h3>История и резервные копии</h3><p class="muted">Данные сохраняются в вашем аккаунте на сервере. Импорт и откат не затрагивают «Работу».</p>${btn('export-finance','Скачать резервную копию','class="secondary"')}<label class="field">Перенести из подготовленного файла<input id="finance-import-file" type="file" accept=".json,application/json"></label>${data.importMeta?btn('rollback-finance','Отменить импорт','class="textlink"'):''}</section></div>`;}
 function render(){const names={overview:'Обзор',incomes:'Доходы',sales:'Продажи',stock:'Склад',cards:'Визитки',salary:'Зарплата',more:'Ещё'};root.innerHTML=`<header class="topbar"><a class="brand" href="/" style="text-decoration:none;color:inherit">Свои деньги<em>.</em></a><a href="/">Все разделы ↗</a></header><main class="fin-main"><div class="heading"><div><p class="muted">Личные финансы</p><h1>Доход</h1></div>${btn('income','＋ Доход','class="primary"')}</div><div class="fin-demo"><b>${data.importMeta?'История Money.xlsx · 2025–2026':'Данные вашего аккаунта'}</b><span>Сохранение на сервере. Сверка и отмена импорта — во вкладке «Ещё».</span></div><nav class="fin-nav" aria-label="Разделы дохода">${Object.entries(names).map(([k,v])=>btn('tab',v,`data-tab="${k}" class="${k===tab?'selected':''}"`)).join('')}</nav>${['overview','incomes','salary'].includes(tab)?`<div class="fin-period"><label>Год<select id="fin-year">${[2025,2026,2027].map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><label>Период<select id="fin-month"><option value="all">Весь год</option>${Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${month===String(i+1).padStart(2,'0')?'selected':''}>${new Date(2026,i,1).toLocaleDateString('ru-RU',{month:'long'})}</option>`).join('')}</select></label></div>`:''}${tab==='overview'?overview():tab==='incomes'?incomesView():tab==='sales'?salesView():tab==='stock'?stockView():tab==='cards'?cardsView():tab==='salary'?salaryView():moreView()}</main>`;
 root.querySelector('#finance-import-file')?.addEventListener('change',e=>{const file=e.target.files[0];if(file)importFile(file);});
 root.querySelector('#card-year')?.addEventListener('change',e=>{cardYear=e.target.value;render();});root.querySelector('#card-month')?.addEventListener('change',e=>{cardMonth=e.target.value;render();});root.querySelector('#card-search')?.addEventListener('input',e=>{cardSearch=e.target.value;const pos=e.target.selectionStart;render();const input=root.querySelector('#card-search');input.focus();input.setSelectionRange(pos,pos);});
 root.querySelector('#fin-year')?.addEventListener('change',e=>{year=Number(e.target.value);render();});root.querySelector('#fin-month')?.addEventListener('change',e=>{month=e.target.value;render();});root.querySelector('#fin-kind')?.addEventListener('change',e=>{kind=e.target.value;render();});
 }
 function incomeForm(id){const x=data.incomes.find(x=>x.id===id);form(x?'Изменить поступление':'Добавить доход',`<label class="field">Категория<select name="category">${options(categories,x?.category||'Зарплата')}</select></label>`+field('Сумма, ₽','amount',x?x.amount/100:'','number','required min="0.01" step="0.01"')+field('Дата поступления','date',x?.date||today(),'date','required')+field('За какой месяц','month',x?.month||today().slice(0,7),'month','required')+field('Банк / счёт','bank',x?.bank||'Т-Банк','text','required maxlength="100"')+field('Комментарий','note',x?.note||'','text','maxlength="500"'),'Сохранить',f=>{const record={id:x?.id||uid(),category:f.get('category'),amount:amount(f.get('amount')),date:f.get('date'),month:f.get('month'),bank:f.get('bank').trim(),note:f.get('note').trim()};if(x)Object.assign(x,record);else data.incomes.push(record);year=Number(record.month.slice(0,4));month=record.month.slice(5);kind='all';tab='incomes';});}
 function saleForm(productId){const p=data.stock.find(x=>x.id===productId);form('Новая продажа',field('Товар / заказ','name',p?.name||'','text','required maxlength="200"')+field('Количество','quantity',1,'number',`required min="1" step="1" ${p?`max="${p.quantity}"`:''}`)+field('Сумма продажи, ₽','revenue',p?p.price/100:'','number','required min="0.01" step="0.01"')+field('Себестоимость заказа, ₽','cost',p?p.cost/100:0,'number','required min="0" step="0.01"')+field('Получено, ₽','received',p?p.price/100:'','number','required min="0" step="0.01"')+field('Дата продажи','date',today(),'date','required')+'<p class="footnote">Сумма продажи и себестоимость — за весь заказ, а не за одну штуку.</p>','Записать продажу',f=>{const quantity=Number(f.get('quantity'));if(!Number.isInteger(quantity)||quantity<1||p&&quantity>p.quantity)throw Error('Проверьте количество.');const revenue=amount(f.get('revenue')),cost=Number(f.get('cost'))===0?0:amount(f.get('cost')),received=Number(f.get('received'))===0?0:amount(f.get('received'));if(received>revenue)throw Error('Получено больше суммы продажи.');data.sales.push({id:uid(),name:f.get('name').trim(),quantity,revenue,cost,received,date:f.get('date'),productId:p?.id||''});if(p)p.quantity-=quantity;tab='sales';});}
 root.addEventListener('click',e=>{const b=e.target.closest('[data-fin]');if(!b||b.disabled)return;const action=b.dataset.fin,id=b.dataset.id;if(action==='export-finance')download({format:'money-finance-backup-v1',data},'finance-backup.json');else if(action==='rollback-finance')form('Отменить импорт','<p>Вернётся состояние раздела «Доход» перед импортом. Текущее состояние будет сохранено отдельной резервной копией на сервере и скачано перед отменой. Раздел «Работа» не изменится.</p>','Отменить импорт',async()=>{download({format:'money-finance-backup-v1',data},'finance-before-rollback.json');const result=await api('/api/finance/rollback',{method:'POST',body:JSON.stringify({revision,importId:data.importMeta.id})});data=result.data;revision=result.revision;lastSynced=structuredClone(data);tab='more';});else if(action==='salary-month')salaryForm(b.dataset.month);else if(action==='card-status'){cardStatus=b.dataset.status;render();}else if(action==='tab'){tab=b.dataset.tab;render();}else if(action==='income'||action==='edit-income')incomeForm(id);else if(action==='month'){month=b.dataset.month;tab='incomes';kind='all';render();}else if(action==='category'){kind=b.dataset.kind;tab='incomes';render();}else if(action==='accounts'){tab='more';render();}else if(action==='card'||action==='edit-card')cardForm(id);else if(action==='card-payment'){const x=data.cards.find(x=>x.id===id),t=cardTotals(x);form('Оплата визиток',field('Сумма оплаты, ₽','amount',t.debt?t.debt/100:'','number','required min="0.01" step="0.01"')+field('Дата оплаты','date',today(),'date','required')+field('Комментарий','note','','text','maxlength="500"'),'Учесть оплату',f=>{const n=amount(f.get('amount'));x.received+=n;(x.payments||=[]).push({id:uid(),amount:n,date:f.get('date'),note:f.get('note')});cardStatus=cardTotals(x).debt?'unpaid':'history';});}else if(action==='sale'||action==='sell-stock')saleForm(id);else if(action==='stock')form('Добавить товар',field('Название','name','','text','required maxlength="200"')+field('Количество','quantity',1,'number','required min="1" step="1"')+field('Закупка за штуку, ₽','cost',0,'number','required min="0" step="0.01"')+field('Цена за штуку, ₽','price','','number','required min="0.01" step="0.01"')+field('Источник','source','','text','maxlength="100"'),'Добавить',f=>{const quantity=Number(f.get('quantity'));if(!Number.isInteger(quantity)||quantity<1)throw Error('Укажите целое количество.');data.stock.push({id:uid(),name:f.get('name').trim(),quantity,cost:Number(f.get('cost'))===0?0:amount(f.get('cost')),price:amount(f.get('price')),source:f.get('source')});});else if(action==='sale-pay'){const x=data.sales.find(x=>x.id===id);form('Оплата продажи',field('Получить, ₽','amount',(x.revenue-x.received)/100,'number','required min="0.01" step="0.01"'),'Учесть оплату',f=>{const n=amount(f.get('amount'));if(n>x.revenue-x.received)throw Error('Сумма больше долга.');x.received+=n;});}else if(action==='account'){const x=data.accounts.find(x=>x.id===id);form('Остаток на счёте',field('Название','name',x.name,'text','required')+field('Остаток, ₽','balance',x.balance/100,'number','required min="0" step="0.01"'),'Сохранить',f=>{x.name=f.get('name');x.balance=Number(f.get('balance'))===0?0:amount(f.get('balance'));});}else if(action==='limits')form('Обязательства',field('Долг по кредиткам, ₽','credit',data.credit/100,'number','required min="0" step="0.01"')+field('Резерв, ₽','reserved',data.reserved/100,'number','required min="0" step="0.01"'),'Сохранить',f=>{for(const k of ['credit','reserved'])data[k]=Number(f.get(k))===0?0:amount(f.get(k));});else if(action==='mortgage'||action==='family'){const x=data[action==='mortgage'?'mortgages':'family'].find(x=>x.id===id);form(action==='mortgage'?'Ипотечный платёж':'Семейный расчёт',field(action==='mortgage'?'Основной долг, ₽':'Сумма расхода, ₽','amount','','number','required min="0.01" step="0.01"')+(action==='mortgage'?field('Проценты, ₽','interest',0,'number','required min="0" step="0.01"'):'')+field('Дата','date',today(),'date','required')+field('Комментарий','note','','text','maxlength="500"'),'Записать',f=>{const n=amount(f.get('amount'));if(n>x.balance)throw Error('Сумма больше остатка долга.');x.balance-=n;x.payments.push({id:uid(),amount:n,interest:Number(f.get('interest')||0)===0?0:amount(f.get('interest')),date:f.get('date'),note:f.get('note')});});}else if(action==='reset')form('Сбросить примеры','<p>Все изменения тестового раздела «Доход» в этом браузере будут заменены исходными примерами. Данные «Работы» сохранятся.</p>','Сбросить',()=>{data=demoFinance();data.cards=data.sales.filter(x=>x.name.startsWith('Визитки')).map(x=>({id:x.id,name:'Тестовый заказчик',date:x.date,quantity:x.quantity,actualQuantity:x.quantity,unitCost:Math.round(x.cost/x.quantity),unitPrice:Math.round(x.revenue/x.quantity),received:x.received,note:''}));data.sales=data.sales.filter(x=>!x.name.startsWith('Визитки'));tab='overview';year=2026;month='all';});});render();
}
